<script>
  import {onMount} from 'svelte';
  import VttIcon from './VttIcon.svelte';
  let {assets=[],scenes=[],folders=[],autoSearch=false,onclose,onimport,onplace,onupdate,onduplicate,ondelete,onaddfolder,onfoldermenu,onsceneopen,onscenerename,onsceneduplicate,onscenedelete}=$props();
  let category=$state('ALL'),collection=$state(''),tag=$state(''),query=$state(''),selected=$state(''),menu=$state(null),fileInput,searchInput;
  const categories=[['ALL','Tous','layers'],['SCENE','Scènes','map'],['MAP','Cartes','map'],['PROP','Accessoires','prop'],['MOUNT','Montures','mount'],['CHARACTER','Personnages','character'],['NOTE','Notes','note']];
  let tags=$derived([...new Set(assets.flatMap(asset=>asset.tags||[]))].sort());
  let visible=$derived((category==='SCENE'?scenes.map(scene=>({...scene,type:'SCENE',preview:scene.thumbnail})):assets).filter(asset=>(category==='ALL'||asset.type===category)&&(!collection||asset.folderId===collection)&&(!tag||(tag==='favorite'?asset.favorite:asset.tags?.includes(tag)))&&(!query||asset.name.toLowerCase().includes(query.toLowerCase()))));
  function rename(asset){const name=prompt('Renommer l’asset',asset.name);if(name?.trim())onupdate(asset.id,{name:name.trim()});}
  function editTags(asset){const value=prompt('Tags séparés par des virgules',(asset.tags||[]).join(', '));if(value!==null)onupdate(asset.id,{tags:[...new Set(value.split(',').map(v=>v.trim()).filter(Boolean))]});menu=null;}
  function move(asset){const choices='Cartes, Accessoires, Montures, Personnages, Notes',value=prompt(`Déplacer vers une catégorie (${choices})`,({MAP:'Cartes',PROP:'Accessoires',MOUNT:'Montures',CHARACTER:'Personnages',NOTE:'Notes'})[asset.type]||'Accessoires');if(value===null)return;const normalized=value.trim().toLowerCase(),type=({cartes:'MAP',carte:'MAP',accessoires:'PROP',accessoire:'PROP',montures:'MOUNT',monture:'MOUNT',personnages:'CHARACTER',personnage:'CHARACTER',notes:'NOTE',note:'NOTE'})[normalized];if(type)onupdate(asset.id,{type});menu=null;}
  function moveFolder(asset){const names=folders.map(folder=>folder.name).join(', '),value=prompt(`Ranger dans un dossier (${names||'aucun dossier'})`,'');if(value===null)return;const folder=folders.find(item=>item.name.toLowerCase()===value.trim().toLowerCase());onupdate(asset.id,{folderId:folder?.id||''});menu=null;}
  onMount(()=>{const close=event=>{if(event.key==='Escape')onclose()};window.addEventListener('keydown',close);if(autoSearch)setTimeout(()=>searchInput?.focus());return()=>window.removeEventListener('keydown',close)});
</script>

<div class="asset-manager-backdrop" role="presentation" onclick={onclose}>
  <section class="asset-manager" role="dialog" aria-modal="true" aria-label="Gestionnaire d’assets" onclick={e=>{e.stopPropagation();menu=null}}>
    <aside class="asset-sidebar"><header><strong>Collections</strong><button onclick={onaddfolder} title="Nouveau dossier"><VttIcon name="add" size={16}/></button></header><button class:active={!collection} onclick={()=>collection=''}><VttIcon name="layers" size={16}/>Tous les assets</button>{#each folders as folder}<button class:active={collection===folder.id} onclick={()=>collection=folder.id} ondblclick={()=>onfoldermenu(folder,'rename')} oncontextmenu={e=>{e.preventDefault();onfoldermenu(folder,'menu')}} title="Double-clic : renommer · Clic droit : options"><span>▰</span>{folder.name}</button>{/each}<header><strong>Tags</strong></header><button class:active={tag==='favorite'} onclick={()=>tag=tag==='favorite'?'':'favorite'}>♥ Favoris</button>{#each tags as value}<button class:active={tag===value} onclick={()=>tag=tag===value?'':value}># {value}</button>{/each}</aside>
    <div class="asset-main"><header><h2>Assets</h2><div class="asset-search"><VttIcon name="search" size={17}/><input bind:this={searchInput} bind:value={query} placeholder="Rechercher"></div><button class="asset-add-main" onclick={()=>fileInput.click()} title="Ajouter" aria-label="Ajouter"><VttIcon name="add" size={19}/></button><button onclick={onclose} aria-label="Fermer">×</button></header>
      <nav class="asset-categories">{#each categories as [key,label,icon]}<button class:active={category===key} onclick={()=>category=key}><VttIcon name={icon} size={16}/>{label}</button>{/each}</nav>
      <div class="asset-grid">{#each visible as asset}<button class="asset-tile" class:selected={selected===asset.id} draggable="true" ondragstart={e=>{e.dataTransfer.setData(asset.type==='SCENE'?'text/vtt-scene':'text/vtt-library-asset',asset.id);e.dataTransfer.effectAllowed='copy'}} onclick={()=>selected=asset.id} ondblclick={()=>asset.type==='SCENE'?onsceneopen(asset.id):onplace(asset)} oncontextmenu={e=>{e.preventDefault();e.stopPropagation();selected=asset.id;menu={asset,x:e.clientX,y:e.clientY}}}><div>{#if asset.preview}<img src={asset.preview} alt="">{:else}<VttIcon name={asset.type?.toLowerCase()||'prop'} size={34}/>{/if}<span class="asset-folder-mark">▰</span></div><span>{asset.name}</span><i onclick={e=>{e.stopPropagation();asset.type==='SCENE'?onscenerename(asset):rename(asset)}}>✎</i></button>{:else}<p class="asset-empty">Aucun asset dans cette vue.</p>{/each}</div>
      <input bind:this={fileInput} hidden type="file" accept="image/*" multiple onchange={e=>{onimport([...e.currentTarget.files],category==='ALL'?'PROP':category);e.currentTarget.value=''}}>
    </div>
  </section>
</div>
{#if menu}<div class="asset-context" style={`left:${menu.x}px;top:${menu.y}px`} onclick={e=>e.stopPropagation()}>{#if menu.asset.type==='SCENE'}<button onclick={()=>{onscenerename(menu.asset);menu=null}}>✎ Renommer</button><button onclick={()=>{onscenedelete(menu.asset);menu=null}}>▰ Supprimer</button>{:else}<button onclick={()=>{onupdate(menu.asset.id,{favorite:!menu.asset.favorite});menu=null}}>♥ {menu.asset.favorite?'Retirer des favoris':'Ajouter aux favoris'}</button><button onclick={()=>editTags(menu.asset)}>◆ Tags</button><button onclick={()=>move(menu.asset)}>▰ Déplacer vers</button><button onclick={()=>moveFolder(menu.asset)}>▰ Ranger dans un dossier</button><button onclick={()=>{if(confirm('Supprimer cet asset de la bibliothèque ?'))ondelete(menu.asset.id);menu=null}}>▰ Supprimer</button>{/if}</div>{/if}
<style>.asset-categories{grid-template-columns:repeat(7,1fr)!important}@media(max-width:760px){.asset-categories{grid-template-columns:repeat(3,1fr)!important}}</style>
